extern void DisplaySleep(void);
extern void DisplayWakeup(void);
extern bool IsDisplayAwake(void);

typedef enum {
  UI_STATE_INIT,
  UI_STATE_IDLE,
  UI_STATE_PAUSE,
  UI_STATE_RESUME,
  UI_STATE_NEXT,
  UI_STATE_PREV,
  UI_STATE_PLAY,
  UI_STATE_STOP,
  UI_STATE_SLEEP,
  UI_STATE_WAKEUP,
} UI_State_t;

