UI_State_t ui_state;
UI_Option_t ui_option;
UI_Control_t ui_control;

void ui_loop(void) {
  if (IsDisplayAwake() && ui_control.sleepTimer <= lv_disp_get_inactive_time(NULL)) {
    DisplaySleep();
  }

  switch (ui_state) {
    case UI_STATE_PLAY:
      player.AutoPlay();
      break;
    case UI_STATE_RESUME:
      player.PauseResume();
      ui_state = UI_STATE_PLAY;
      break;
    case UI_STATE_PAUSE:
      player.PauseResume();
      ui_state = UI_STATE_IDLE;
      break;
    case UI_STATE_NEXT:
      player.PlayNext();
      lv_obj_set_state(ui_ButtonPlay, LV_STATE_CHECKED, true);
      ui_state = UI_STATE_PLAY;
      break;
    case UI_STATE_PREV:
      player.PlayPrev();
      lv_obj_set_state(ui_ButtonPlay, LV_STATE_CHECKED, true);
      ui_state = UI_STATE_PLAY;
      break;
    case UI_STATE_STOP:
      player.StopPlay();
      ui_state = UI_STATE_IDLE;
      break;
    case UI_STATE_INIT:
      player.begin();
      player.ScanFileList(MP3_PATH_CONFIG);
      player.SortFileList(true);
      player.SetVolume(MP3_VOLUME_INI);
      player.SetPlayNo(ui_control.playNo);
      lv_slider_set_value(ui_Volume, MP3_VOLUME_INI, LV_ANIM_OFF);
      ui_state = UI_STATE_IDLE;

      // start playing: it makes ui_state to UI_STATE_RESUME
      lv_obj_set_state(ui_ButtonPlay, LV_STATE_CHECKED, true);
      lv_obj_send_event(ui_ButtonPlay, LV_EVENT_CLICKED, NULL);
      break;
    case UI_STATE_IDLE:
    default:
      break;
  }
}

